  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  return projectRepo.updateProject(input);
}

/**
 * Archiving a project cascades to its issues by default — leaving live issues
 * behind an archived project is the drift this flag exists to prevent.
 */
export async function archiveProject(
  actor: Actor,
  input: ArchiveProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const issuesArchived = input.archiveIssues
    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
    : 0;

  const archived = await projectRepo.archiveProject(
    input.orgId,
    input.projectId,
  );

  await emit("project.archived", {
    ...actorEnvelope(actor),
    projectId: archived.id,
    issuesArchived,
  });

  return archived;
}

/** Restore does not un-archive the issues: they are restored individually. */
export async function restoreProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));

  const restored = await projectRepo.restoreProject(orgId, projectId);

  await emit("project.restored", {
    ...actorEnvelope(actor),
    projectId: restored.id,
  });

  return restored;
}

export async function getProject(
  actor: Actor,
  orgId: OrgId,
  slug: string,
): Promise<ProjectWithStats> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectBySlug(orgId, slug),
    "Project",
    slug,
  );
  assertCan(actor, "project:read", projectResource(project));

  return {
    project,
    stats: await projectRepo.getProjectStats(orgId, project.id),
  };
}

export async function listProjects(
  actor: Actor,
  input: ListProjectsInput,
): Promise<Page<ProjectWithStats>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:read", orgResource(input.orgId));

  const page = await projectRepo.listProjects(input);

  const items = await Promise.all(
    page.items.map(async (project) => ({
      project,
      stats: await projectRepo.getProjectStats(input.orgId, project.id),
    })),
  );

  return { items, nextCursor: page.nextCursor, total: page.total };
}

/**
 * Slug preview used by both the create form and `createProject`, so what the
 * user sees while typing is what the row ends up with.
 */
export async function suggestProjectSlug(
  orgId: OrgId,
  name: string,
): Promise<string> {
  const taken = await projectRepo.listTakenProjectSlugs(orgId);
  return uniqueSlug(name, taken);
}

/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}
/**
 * Webhook endpoints and their delivery attempts.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, webhookDeliveries, webhookEndpoints } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { CreateWebhookInput, UpdateWebhookInput } from "@/schemas/webhook";
import type {
  WebhookDeliveryRow,
  WebhookEndpointRow,
} from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, WebhookId } from "@/types/common";

export async function listEndpoints(
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  return getDb()
    .select()
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .orderBy(asc(webhookEndpoints.createdAt))
    .all();
}

export async function insertEndpoint(
  input: CreateWebhookInput,
  secret: string,
): Promise<WebhookEndpointRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookEndpoints)
    .values({
      id: newId(),
      orgId: input.orgId,
      url: input.url,
      secret,
      eventTypes: JSON.stringify(input.eventTypes),
      enabled: true,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

export async function updateEndpoint(
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  const row = getDb()
    .update(webhookEndpoints)
    .set({
      ...(input.url === undefined ? {} : { url: input.url }),
      ...(input.eventTypes === undefined
        ? {}
        : { eventTypes: JSON.stringify(input.eventTypes) }),
      ...(input.enabled === undefined ? {} : { enabled: input.enabled }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, input.orgId),
        eq(webhookEndpoints.id, input.webhookId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Webhook ${input.webhookId} not found`);
  return row;
}

export async function deleteEndpoint(
  orgId: OrgId,
  webhookId: WebhookId,
): Promise<void> {
  const db = getDb();
  db.delete(webhookDeliveries)
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.endpointId, webhookId),
      ),
    )
    .run();
  db.delete(webhookEndpoints)
    .where(
      and(
        orgPredicate(webhookEndpoints.orgId, orgId),
        eq(webhookEndpoints.id, webhookId),
      ),
    )
    .run();
}

/** The `webhooks` quota compares against this. */
export async function countEndpoints(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(webhookEndpoints)
    .where(orgPredicate(webhookEndpoints.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function enqueueDelivery(
  orgId: OrgId,
  endpointId: string,
  eventType: string,
  payload: string,
): Promise<WebhookDeliveryRow> {
  const stamp = toIsoTimestamp(new Date());
  return getDb()
    .insert(webhookDeliveries)
    .values({
      id: newId(),
      orgId,
      endpointId,
      eventType,
      payload,
      status: "pending",
      attempts: 0,
      lastError: null,
      deliveredAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
}

/**
 * Claims a batch for the delivery job. Cross-tenant on purpose — the queue is
 * drained by a background worker, not by a request — and the attempt counter
 * is bumped on claim so a crashed worker cannot retry forever.
 */
export async function claimPendingDeliveries(
  limit: number,
): Promise<readonly WebhookDeliveryRow[]> {
  const db = getDb();
  const pending = db
    .select()
    .from(webhookDeliveries)
    .where(eq(webhookDeliveries.status, "pending"))
    .orderBy(asc(webhookDeliveries.createdAt))
    .limit(Math.max(1, limit))
    .all();

  return pending.map((row) =>
    db
      .update(webhookDeliveries)
      .set({
        attempts: row.attempts + 1,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(eq(webhookDeliveries.id, row.id))
      .returning()
      .get(),
  );
}

export async function markDelivered(
  orgId: OrgId,
  deliveryId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({ status: "delivered", deliveredAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}

export async function markDeliveryFailed(
  orgId: OrgId,
  deliveryId: string,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.id, deliveryId),
      ),
    )
    .run();
}
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}
/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}
/**
 * Shared JSON helpers for the route handlers.
 *
 * Owner D. Every handler under `src/app/api` returns the same envelope as the
 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
 * is the single mapping from domain error code to HTTP.
 */

import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
import type { AppErrorShape, ApiErrorBody } from "@/types/api";

/** Turns any thrown value into the JSON error envelope with the right status. */
export function errorResponse(error: unknown): Response {
  const shape: AppErrorShape = toAppError(error);
  const body: ApiErrorBody = { error: shape };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });
}

/** Builds the envelope for a failure the handler detected itself. */
export function failure(
  code: AppErrorShape["code"],
  message: string,
): Response {
  const body: ApiErrorBody = { error: { code, message } };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[code] });
}

/**
 * Cron endpoints are protected by a shared secret rather than a session — they
 * are called by the platform scheduler, which has no cookie jar.
 */
export function assertCronSecret(request: Request): void {
  const expected = process.env.TASKFLOW_CRON_SECRET;
  if (expected === undefined || expected.length === 0) {
    // No secret configured means cron is disabled rather than wide open.
    throw new CronAuthError("Cron trigger is not configured.");
  }
  if (request.headers.get("x-taskflow-cron") !== expected) {
    throw new CronAuthError("Bad cron secret.");
  }
}

export class CronAuthError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message: string) {
    super(message);
    this.name = "CronAuthError";
  }
}
/**
 * Loads the three things every page under `[orgSlug]` needs: the organization,
 * the caller's `Actor` inside it, and the feature-flag snapshot.
 *
