/**
 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
 */
import { createLogger } from "@/lib/logger";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type QueuedJob = {
  id: string;
  kind: JobKind;
  runAt: IsoTimestamp;
  attempts: number;
  payload: Readonly<Record<string, unknown>>;
};

export type JobKind =
  | "digest-email"
  | "overdue-issues"
  | "webhook-delivery"
  | "usage-rollup"
  | "search-reindex"
  | "cleanup-archived"
  | "trial-expiry";

/** Attempts after which a job is dropped rather than retried again. */
const MAX_ATTEMPTS = 5;

/** How many jobs `drain()` takes in one pass when no limit is given. */
const DEFAULT_DRAIN = 25;

const logger = createLogger("job-queue");

/**
 * The queue lives in module scope: Taskflow runs one server process and the
 * scheduler is started from `instrumentation.ts`, so there is no second
 * consumer to coordinate with. Swapping this for a real broker means
 * reimplementing these four functions and nothing else.
 */
const pending: QueuedJob[] = [];

/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
export function enqueue(job: QueuedJob): void {
  if (pending.some((queued) => queued.id === job.id)) return;
  pending.push(job);
}

/**
 * Runs everything that is due, oldest first. A handler that throws is put back
 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
 * — an infinitely retrying job is worse than a lost one.
 */
export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
  const now = new Date().toISOString();
  const due = pending
    .filter((job) => job.runAt <= now)
    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
    .slice(0, Math.max(0, limit));

  let completed = 0;

  for (const job of due) {
    remove(job.id);

    try {
      await runHandler(job);
      completed += 1;
    } catch (error) {
      const attempts = job.attempts + 1;

      if (attempts >= MAX_ATTEMPTS) {
        logger.error("job dropped after max attempts", {
          id: job.id,
          kind: job.kind,
          attempts,
        });
        continue;
      }

      pending.push({
        ...job,
        attempts,
        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
      });

      logger.warn("job retry scheduled", {
        id: job.id,
        kind: job.kind,
        attempts,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return completed;
}

export function pendingCount(): number {
  return pending.length;
}

/** Test hook: empties the queue. Never call this from application code. */
export function resetQueue(): void {
  pending.length = 0;
}

/** 1s, 2s, 4s, 8s … capped at one minute. */
function backoffMs(attempts: number): number {
  return Math.min(60_000, 2 ** (attempts - 1) * 1_000);
}

function remove(id: string): void {
  const at = pending.findIndex((job) => job.id === id);
  if (at >= 0) pending.splice(at, 1);
}

/**
 * Dispatches one queued job to its runner. The imports are dynamic so the
 * queue module stays free of a cycle: every job module imports this one to
 * enqueue follow-up work.
 */
async function runHandler(job: QueuedJob): Promise<void> {
  const now = new Date();

  switch (job.kind) {
    case "digest-email": {
      const { runDigestEmailJob } = await import("./digest-email-job");
      await runDigestEmailJob(now);
      return;
    }
    case "overdue-issues": {
      const { runOverdueIssueJob } = await import("./overdue-issue-job");
      await runOverdueIssueJob(now);
      return;
    }
    case "webhook-delivery": {
      const { runWebhookDeliveryJob } = await import("./webhook-delivery-job");
      await runWebhookDeliveryJob(now);
      return;
    }
    case "usage-rollup": {
      const { runUsageRollupJob } = await import("./usage-rollup-job");
      await runUsageRollupJob(now);
      return;
    }
    case "search-reindex": {
      const { runSearchReindexJob } = await import("./search-reindex-job");
      const orgId = job.payload.orgId;
      if (typeof orgId !== "string") return;
      await runSearchReindexJob(orgId as Parameters<typeof runSearchReindexJob>[0]);
      return;
    }
    case "cleanup-archived": {
      const { runCleanupArchivedJob } = await import("./cleanup-archived-job");
      await runCleanupArchivedJob(now);
      return;
    }
    case "trial-expiry": {
      const { runTrialExpiryJob } = await import("./trial-expiry-job");
      await runTrialExpiryJob(now);
      return;
    }
  }
}
/**
 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
 */
import { createLogger } from "@/lib/logger";
import { drain, enqueue, pendingCount } from "./queue";
import { toIsoTimestamp } from "@/types/common";
import type { JobKind } from "./queue";

/** How often `tick()` runs once the scheduler is started. */
const TICK_INTERVAL_MS = 60_000;

/** Minimum gap between two runs of the same job kind, in minutes. */
const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
  "digest-email": 60,
  "overdue-issues": 60,
  "webhook-delivery": 1,
  "usage-rollup": 15,
  "search-reindex": 1_440,
  "cleanup-archived": 1_440,
  "trial-expiry": 360,
};

const logger = createLogger("job-scheduler");

let timer: ReturnType<typeof setInterval> | null = null;
const lastRunAt = new Map<JobKind, number>();

/**
 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
 * keeps a process alive — a scheduler that blocks shutdown is worse than one
 * that misses the last tick.
 */
export function startScheduler(): void {
  if (timer !== null) return;

  timer = setInterval(() => {
    void tick(new Date()).catch((error: unknown) => {
      logger.error("scheduler tick failed", {
        reason: error instanceof Error ? error.message : String(error),
      });
    });
  }, TICK_INTERVAL_MS);

  timer.unref?.();
  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
}

export function stopScheduler(): void {
  if (timer === null) return;
  clearInterval(timer);
  timer = null;
  lastRunAt.clear();
}

export function isSchedulerRunning(): boolean {
  return timer !== null;
}

/**
 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
 * out from the interval so tests can drive it with an explicit clock instead
 * of waiting a minute.
 */
export async function tick(now: Date): Promise<void> {
  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
    if (!isDue(kind, now)) continue;

    lastRunAt.set(kind, now.getTime());
    enqueue({
      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
      kind,
      runAt: toIsoTimestamp(now),
      attempts: 0,
      payload: {},
    });
  }

  const completed = await drain();
  if (completed > 0 || pendingCount() > 0) {
    logger.debug("tick complete", { completed, pending: pendingCount() });
  }
}

function isDue(kind: JobKind, now: Date): boolean {
  const previous = lastRunAt.get(kind);
  if (previous === undefined) return true;
  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
}
import { assertActiveOrganization } from "./_support";
/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  await assertActiveOrganization(actor.orgId);
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  await assertActiveOrganization(actor.orgId);
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { assertNotArchived, archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Slug lookup for the `[orgSlug]` routes. A closed workspace keeps its slug
 * but is never resolved for application access.
 */
export async function findOrgBySlug(slug: string, includeArchived = false): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), includeArchived ? undefined : isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(and(eq(members.userId, userId), eq(members.status, "active"), isNull(members.archivedAt), isNull(organizations.archivedAt)))
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  return getDb().transaction((tx) => {
    const current = tx.select().from(organizations)
      .where(eq(organizations.id, orgId)).get();
    if (!current) throw new Error(`Organization ${orgId} not found`);
    assertNotArchived("Organization", orgId, current);

    const patch = archivePatch();
    const row = tx.update(organizations).set(patch)
      .where(and(eq(organizations.id, orgId), isNull(organizations.archivedAt)))
      .returning().get();
    if (!row) throw new Error(`Organization ${orgId} not found`);

    tx.update(subscriptions).set({
      status: "canceled", cancelAt: patch.archivedAt,
      currentPeriodEnd: patch.archivedAt, updatedAt: patch.updatedAt,
    }).where(eq(subscriptions.orgId, orgId)).run();
    return toOrganization(row);
  });
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}

