import * as notificationService from \"@/server/services/notification-service\";
import { registerActivityListeners } from \"@/server/services/activity-service\";
import { registerWebhookListeners } from \"@/server/services/webhook-service\";
import { buildDigest } from \"@/server/services/digest-service\";
import { runSearchReindexJob } from \"@/server/jobs/search-reindex-job\";
import { runTrialExpiryJob } from \"@/server/jobs/trial-expiry-job\";
import { runWebhookDeliveryJob } from \"@/server/jobs/webhook-delivery-job\";
import { getDb, activities, webhookDeliveries } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import { createTenant, useTemporaryDatabase } from \"./_support/fixtures\";
import type { Tenant } from \"./_support/fixtures\";

let cleanup: () => void;
let closed: Tenant;
let live: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  closed = await createTenant(\"closing\");
  live = await createTenant(\"remaining\");
});
afterAll(() => {
  resetEventBus();
  cleanup();
});

it(\"refuses a wrong confirmation, then closes access and billing immediately\", async () => {
  const input = { orgId: closed.org.id, confirmSlug: closed.org.slug };
  await expect(organizationService.deleteOrganization(closed.actors.owner, {
    ...input, confirmSlug: \"wrong\",
  })).rejects.toThrow(\"confirmation\");
  expect((await orgRepo.findOrgById(closed.org.id))?.archivedAt).toBeNull();

  await invitationRepo.insertInvitation(closed.org.id, {
    orgId: closed.org.id, email: \"invitee@example.test\", role: \"member\", expiresInDays: 90,
  }, closed.userIds.owner, hashToken(\"pending-token\"));
  const endpoint = await webhookRepo.insertEndpoint({
    orgId: closed.org.id, url: \"https://example.test/hook\", eventTypes: [\"billing.plan_changed\"],
  }, \"secret\");
  const queued = await webhookRepo.enqueueDelivery(closed.org.id, endpoint.id, \"billing.plan_changed\", \"{}\");
  await usageRepo.recomputeUsage(closed.org.id);
  await usageRepo.recomputeUsage(live.org.id);

  const org = await organizationService.deleteOrganization(closed.actors.owner, input);
  const subscription = await subscriptionRepo.findSubscription(org.id);
  expect(subscription?.status).toBe(\"canceled\");
  expect(subscription?.cancelAt).toBe(org.archivedAt);
  expect(subscription?.currentPeriodEnd).toBe(org.archivedAt);
  await expect(organizationService.deleteOrganization(closed.actors.owner, input))
    .rejects.toMatchObject({ code: \"conflict\" });
  expect(await orgRepo.findOrgBySlug(org.slug)).toBeNull();
  expect(await organizationService.listOrganizationsForUser(closed.userIds.member)).toEqual([]);
  expect(await memberService.resolveActor(closed.userIds.owner, org.id)).toBeNull();
  const principal = {
    userId: closed.userIds.owner, activeOrgId: org.id,
    expiresAt: toIsoTimestamp(new Date(Date.now() + 86_400_000)),
  };
  expect(await sessionService.resolveActorForOrg(principal, org.slug)).toBeNull();
  await expect(sessionService.switchActiveOrg(principal, { orgId: org.id })).rejects.toThrow();
  await expect(projectService.listProjects(closed.actors.member, {
    orgId: org.id, cursor: null, limit: 25, includeArchived: true,
  })).rejects.toMatchObject({ code: \"not_found\" });
  await expect(invitationService.acceptInvitation(live.userIds.member, { token: \"pending-token\" })).rejects.toThrow();
  expect(await notificationService.notify(org.id, \"issue_overdue\", [closed.userIds.member], {
    title: \"Overdue\", body: \"Due\", href: \"/issues\", actorId: null,
  })).toEqual([]);
  const stamp = toIsoTimestamp(new Date());
  expect(await buildDigest(org.id, closed.userIds.member, stamp, stamp)).toBeNull();
  expect(await usageRepo.listOrgIdsForRollup(100)).not.toContain(org.id);
  expect((await runSearchReindexJob(org.id)).processed).toBe(0);
  await runWebhookDeliveryJob(new Date());
  expect(getDb().select().from(webhookDeliveries).all().find((row) => row.id === queued.id))
    .toMatchObject({ status: \"pending\", attempts: 0, deliveredAt: null });
  registerActivityListeners();
  registerWebhookListeners();
  await emit(\"billing.plan_changed\", {
    orgId: org.id, actorId: null, occurredAt: stamp, from: \"growth\", to: \"free\",
  });
  expect(getDb().select().from(activities).all()).toEqual([]);
  expect(getDb().select().from(webhookDeliveries).all()).toHaveLength(1);
  await runTrialExpiryJob(new Date(Date.now() + 90 * 86_400_000));
  expect((await subscriptionRepo.findSubscription(org.id))?.plan).toBe(\"growth\");
  expect((await projectService.listProjects(live.actors.member, {
    orgId: live.org.id, cursor: null, limit: 25,
  })).total).toBe(1);
  const replacement = await organizationService.createOrganization(live.userIds.owner, {
    name: \"Replacement\", slug: org.slug, plan: \"free\",
  });
  expect(replacement.slug).not.toBe(org.slug);
});
